LEVEL = 1
CFG = {1: 2, 2: 4, 3: 6}
N = CFG[LEVEL]
results = []
for i in range(N):
    ok = (i % 3 != 2)  # every third drill finds a problem
    results.append(("drill-%d" % (i + 1), "PASS" if ok else "FAIL-needs-fix"))
for name, r in results:
    print(name, r)
print("proven fallbacks:", sum(1 for _, r in results if r == "PASS"), "/", N)

