LEVEL = 1
CFG = {1: ["arc-a"], 2: ["arc-a", "arc-b"], 3: ["arc-a", "arc-b", "arc-c"]}
bridges = {a: True for a in CFG[LEVEL]}
if "arc-b" in bridges:
    bridges["arc-b"] = False  # this bridge is down
route = next((a for a in CFG[LEVEL] if bridges[a]), None)
print("bridges:", bridges, "| routed via:", route)

